  const q = questions[step];
  return <><PageHero locale={locale} route="/pet-match" /><main className="container quiz-shell"><div className="quiz-progress"><span style={{ width: `${((step + 1) / questions.length) * 100}%` }} /></div><p>{l("Question", "Câu")} {step + 1} / {questions.length}</p><h2>{l(q[0], q[1])}</h2><div className="choice-list">{q[2].map((x, i) => <button key={x} onClick={() => { setAnswers([...answers, x]); setStep(step + 1); }}><span>{String.fromCharCode(65 + i)}</span>{x}</button>)}</div><p className="fineprint">{l("Your result is a conversation starter, not an adoption decision.", "Kết quả là điểm khởi đầu để tìm hiểu, không phải quyết định nhận nuôi.")}</p></main></>;
