function SitLesson({ locale }: { locale: Locale }) {
  const l = (en: string, vi: string) => localized(locale, en, vi); const steps = [l("Get your dog’s attention in a quiet space.", "Thu hút sự chú ý của chó ở nơi yên tĩnh."), l("Hold a treat close to the nose.", "Giữ đồ thưởng gần mũi."), l("Move the treat slowly upward.", "Từ từ đưa đồ thưởng lên trên."), l("When your dog sits naturally, mark the behavior.", "Khi chó tự nhiên ngồi xuống, đánh dấu hành vi."), l("Reward immediately.", "Thưởng ngay lập tức."), l("Repeat in short, upbeat sessions.", "Lặp lại trong các buổi ngắn, vui vẻ.")]; const [done, setDone] = useState(0); const [success, setSuccess] = useState(7); const [started, setStarted] = useState(false);
  return <main className="container lesson-page"><div className="lesson-title"><p className="eyebrow">{l("Training academy · Puppy foundations", "Học viện huấn luyện · Nền tảng chó con")}</p><h1>{l("Teach your dog to sit", "Dạy chó ngồi")}</h1><p>{l("Objective: build a clear, comfortable sit cue using reward-based practice.", "Mục tiêu: xây tín hiệu ngồi rõ ràng, thoải mái bằng luyện tập có thưởng.")}</p><div className="fact-chips"><span>{l("Beginner", "Cơ bản")}</span><span>3–5 {l("minutes", "phút")}</span><span>{l("Treats + quiet room", "Đồ thưởng + phòng yên tĩnh")}</span></div></div><div className="lesson-layout"><section><h2>{l("Step by step", "Từng bước")}</h2>{steps.map((x, i) => <button className={`step-row ${i < done ? "done" : ""} ${i === done ? "current" : ""}`} key={x} onClick={() => started && setDone(Math.max(done, i + 1))}><span>{i < done ? "✓" : i + 1}</span><p>{x}</p></button>)}</section><aside className="session-card"><p className="eyebrow">{l("Live session", "Buổi tập trực tiếp")}</p><div className="session-ring"><b>{success}</b><span>/ 10</span></div><p>{l("successful attempts", "lần thành công")}</p><div className="session-actions"><button className="button primary" onClick={() => { setStarted(true); if (done < steps.length) setDone(done + 1); }}>{started ? l("Complete step", "Hoàn thành bước") : l("Start session", "Bắt đầu buổi tập")}</button><button onClick={() => setSuccess(Math.min(10, success + 1))}>+ {l("Record success", "Ghi nhận thành công")}</button><button>{l("Record difficulty", "Ghi nhận khó khăn")}</button></div><div className="stop-note"><b>{l("When to stop", "Khi nào nên dừng")}</b><p>{l("Pause if your dog disengages, shows stress, or stops taking treats. End on an easy win.", "Tạm dừng nếu chó mất tập trung, căng thẳng hoặc không nhận đồ thưởng. Kết thúc bằng một thành công dễ.")}</p></div></aside></div></main>;
}

